#include "flint.h"
#include "mpn_extras.h"
#include "fmpz.h"
#include "fixed.h"

/* Arguments are stored as (low, high) 64-bit halves -- two limbs on
   64-bit systems, four on 32-bit -- so any argument below 2^128 is
   plain data; packed coefficient data as 32-bit words in
   little-endian order, paired into limbs on 64-bit systems (as
   arb/exp_tab.c) */
#if FLINT_BITS == 64
#define X(lo, hi) UWORD(lo), UWORD(hi)
#else
#define X(lo, hi) (ulong) (lo ## ULL), (ulong) ((lo ## ULL) >> 32), \
                  (ulong) (hi ## ULL), (ulong) ((hi ## ULL) >> 32)
#endif
#if FLINT_BITS == 64
#define Z2(a,b) UWORD(0x ## b ## a)
#else
#define Z2(a,b) UWORD(0x ## a), UWORD(0x ## b)
#endif
#define Z8(a,b,c,d,e,f,g,h) Z2(a,b), Z2(c,d), Z2(e,f), Z2(g,h),

/* The coefficient matrix of a set is bit packed: entry k = i num + j
   occupies the cbits bits from bit k cbits of the array c, in two's
   complement, cbits being one more than the largest magnitude's bit
   length.  The arguments are FIXED_MACHIN_X_LIMBS limbs each (128
   bits). */


/* Machin-type sets for the logarithms of the first primes and for
   the arguments of the first nonreal Gaussian primes:

       log p_i = (1/den) sum_j c[i][j] atanh(1/x_j)       (gaussian = 0)
       arg pi_i = (1/den) sum_j c[i][j] atan(1/x_j)       (gaussian = 1)

   -- the c matrices are square, one series per value.  The
   logarithm sets come from Luca-Najman smooth neighbours (x^2 - 1
   smooth over the primes), the Gaussian ones from x^2 + 1 smooth
   over the norms (examples/machin_set.c).  Those for up to 24 primes
   and up to 16 Gaussian primes are arb's (formerly in
   arb/log_primes.c).  The sets for 20, 24 and 32 Gaussian primes and
   for 32 primes are optimal: every smooth x below 2^126 was
   enumerated by Pell equations (arguments of 29-46 bits for 20 and
   24 Gaussian primes, 43-53 bits for 32 Gaussian primes, 63-76 bits
   for 32 primes).  Those for 40 and 48 of each kind come from a
   heuristic search (sieve, smaller sets as seeds, combination rounds
   and extension): arguments of 68-76 bits for 40 primes, 76-88 bits
   for 48 primes, 44-53 bits for 40 Gaussian primes and 46-55 bits for
   48 Gaussian primes.  fixed_machin_table returns the smallest set
   covering a given count.  The same data serves 32-bit systems (arb
   kept smaller 32-bit-only sets, which are dropped). */


/* one coefficient doesn't fit in 64 bits */

