static const fixed_machin_struct machin_atan[] = {
    { 3, atan_3_x, atan_3_den, atan_3_c, atan_3_cbits },
    { 4, atan_4_x, atan_4_den, atan_4_c, atan_4_cbits },
    { 8, atan_8_x, atan_8_den, atan_8_c, atan_8_cbits },
    { 12, atan_12_x, atan_12_den, atan_12_c, atan_12_cbits },
    { 13, atan_13_x, atan_13_den, atan_13_c, atan_13_cbits },
    { 16, atan_16_x, atan_16_den, atan_16_c, atan_16_cbits },
    { 20, atan_20_x, atan_20_den, atan_20_c, atan_20_cbits },
    { 24, atan_24_x, atan_24_den, atan_24_c, atan_24_cbits },
    { 32, atan_32_x, atan_32_den, atan_32_c, atan_32_cbits },
    { 40, atan_40_x, atan_40_den, atan_40_c, atan_40_cbits },
    { 48, atan_48_x, atan_48_den, atan_48_c, atan_48_cbits },
};

const fixed_machin_struct *
fixed_machin_table(int gaussian, slong num)
{
    const fixed_machin_struct * tab = gaussian ? machin_atan : machin_log;
    slong len = gaussian ? (slong) (sizeof(machin_atan) / sizeof(machin_atan[0]))
                         : (slong) (sizeof(machin_log) / sizeof(machin_log[0]));
    slong i;

    for (i = 0; i < len; i++)
        if (tab[i].num >= num)
            return tab + i;
    return NULL;
}

/* q = x_i of the set */
void
fixed_machin_get_x(fmpz_t q, const fixed_machin_struct * tab, slong i)
{
    fmpz_set_ui_array(q, tab->x + i * FIXED_MACHIN_X_LIMBS,
        FIXED_MACHIN_X_LIMBS);
}

/* c = c[i][j] of the set: entry k = i num + j occupies the bits
   [k cbits, (k + 1) cbits) of the packed array, in two's complement */
void
fixed_machin_get_c(fmpz_t c, const fixed_machin_struct * tab, slong i, slong j)
{
    slong k = i * tab->num + j, cbits = tab->cbits;
    slong off = k * cbits, lo = off / FLINT_BITS, sh = off % FLINT_BITS;
    slong nl = (cbits + sh + FLINT_BITS - 1) / FLINT_BITS, t, top, rem;
    ulong buf[8];

    FLINT_ASSERT(nl <= 8);
    for (t = 0; t < nl; t++)
        buf[t] = tab->c[lo + t];
    if (sh > 0)
        mpn_rshift(buf, buf, nl, sh);
    /* clear the bits above the field */
    top = cbits / FLINT_BITS;
    rem = cbits % FLINT_BITS;
    if (rem > 0)
    {
        buf[top] &= (UWORD(1) << rem) - 1;
        nl = top + 1;
    }
    else
        nl = top;
    fmpz_set_ui_array(c, buf, nl);
    /* sign: the field's top bit */
    if ((buf[(cbits - 1) / FLINT_BITS] >> ((cbits - 1) % FLINT_BITS)) & 1)
    {
        fmpz_t two;
        fmpz_init_set_ui(two, 1);
        fmpz_mul_2exp(two, two, cbits);
        fmpz_sub(c, c, two);
        fmpz_clear(two);
    }
}

void
fixed_machin_get_c_row(fmpz * row, const fixed_machin_struct * tab, slong i)
{
    slong j;
    for (j = 0; j < tab->num; j++)
        fixed_machin_get_c(row + j, tab, i, j);
}

slong
fixed_machin_table_max(int gaussian)
{
    return gaussian ? machin_atan[sizeof(machin_atan) / sizeof(machin_atan[0]) - 1].num
                    : machin_log[sizeof(machin_log) / sizeof(machin_log[0]) - 1].num;
}
